example.code:
[<Pojo>]
type Person(name: string, ?age: int) =
    member val name = name
    member val age = age

let p = Person("Alice")

// Typescript
export interface Person {
    name: string,
    age?: number
}

export const p: Person = { name: "Alice" }

remarks.code:
[<Py.DataClass>]
type User(name: string, age: int) = ...
// Generates:
// class User:
//     name: str
//     age: int

[<BaseModel>]
type User(name: string, age: int) = ...
// Generates class with class-level attributes, no __init__
